import { kebabCase } from 'es-toolkit/string';
import { keyBy } from 'es-toolkit/array';
import { truncate } from 'es-toolkit/compat/string/truncate';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function toSlug(label: string): string {
  return kebabCase(label);
}

export function byNameKey(rows: Row[]): Record<string, Row> {
  return keyBy(rows, (r) => r.name);
}

export function preview(text: string): string {
  return truncate(text, { length: 24 });
}
EOF
npm run size -- src/module.ts 2>&1 | tail -1; npm run size -- out/module.ts 2>&1 | tail -3
cat > out/t.mjs <<'EOF'
import { build } from 'esbuild';
import _ from 'lodash';
const r = await build({entryPoints:['out/module.ts'],bundle:true,format:'esm',write:false,platform:'node'});
const m = await import('data:text/javascript;base64,'+Buffer.from(r.outputFiles[0].text).toString('base64'));
const A='ABCabcXYZxyz0123456789 -_.';let bad=0;
for(let i=0;i<20000;i++){let s='';const n=Math.random()*41|0;for(let j=0;j<n;j++)s+=A[Math.random()*A.length|0];
 if(_.kebabCase(s)!==m.toSlug(s)){if(bad++<5)console.log(JSON.stringify(s),_.kebabCase(s),m.toSlug(s))}
 let t='';const k=Math.random()*201|0;for(let j=0;j<k;j++)t+=String.fromCharCode(32+Math.random()*95|0);
 if(_.truncate(t,{length:24})!==m.preview(t))bad++;}
console.log('bad',bad);
EOF
node out/t.mjs

